package com.bank.vanity;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

public class VanityCodeSuggester {

    private static final Logger log = Logger.getLogger(VanityCodeSuggester.class.getName());
    private static final Map<Character, String> KEYPAD = Map.of(
        '2', "abc", '3', "def", '4', "ghi", '5', "jkl",
        '6', "mno", '7', "pqrs", '8', "tuv", '9', "wxyz");

    public List<String> letterCombinations(String digits) {
        List<String> result = new ArrayList<>();
        if (digits == null || digits.isEmpty()) return result; // empty ⇒ empty list
        backtrack(digits, 0, new StringBuilder(), result);
        log.info(() -> "Suggested " + result.size() + " vanity codes for " + digits);
        return result;
    }

    private void backtrack(String digits, int index, StringBuilder sb, List<String> result) {
        if (index == digits.length()) { result.add(sb.toString()); return; }
        String letters = KEYPAD.get(digits.charAt(index));
        for (int i = 0; i < letters.length(); i++) {
            sb.append(letters.charAt(i));
            backtrack(digits, index + 1, sb, result);
            sb.deleteCharAt(sb.length() - 1);     // backtrack
        }
    }
}
