package com.bank.vanity;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class LetterCombinationsDemo {

    private static final Logger log = Logger.getLogger(LetterCombinationsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Payee Vanity Code Suggester");
        VanityCodeSuggester s = new VanityCodeSuggester();
        s.letterCombinations("23").forEach(code -> log.info("Code: " + code));
    }
}
